import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  IconChevronRight,
  IconDots,
  IconHome,
  IconSlash,
} from "@tabler/icons-react";
import { cn } from "@/lib/utils";

/* ─── Types ─────────────────────────────────────────────────── */

export type BreadcrumbVariant =
  | "default"
  | "with-icons"
  | "collapsed"
  | "dropdown"
  | "custom-separator";

export interface BreadcrumbProps extends React.HTMLAttributes<HTMLElement> {
  variant?: BreadcrumbVariant;
  /** Custom separator node — used by all variants but most visible in `custom-separator`. */
  separator?: React.ReactNode;
  /** For collapsed/dropdown variants: maximum visible items before collapsing (default 3). */
  maxItems?: number;
}

export interface BreadcrumbItemProps
  extends React.HTMLAttributes<HTMLLIElement> {
  /** Link href — omit for the current (last) page. */
  href?: string;
  /** Optional leading icon. */
  icon?: React.ReactNode;
  /** Mark as the current page — renders as static text. */
  isCurrentPage?: boolean;
}

export interface BreadcrumbSeparatorProps
  extends React.HTMLAttributes<HTMLLIElement> {
  children?: React.ReactNode;
}

/* ─── Context ───────────────────────────────────────────────── */

type BreadcrumbContextValue = {
  variant: BreadcrumbVariant;
  separator: React.ReactNode;
};

const BreadcrumbContext = React.createContext<BreadcrumbContextValue>({
  variant: "default",
  separator: null,
});

/* ─── Easing ────────────────────────────────────────────────── */

const EASE_OUT: [number, number, number, number] = [0.23, 1, 0.32, 1];

/* ─── Default separators per variant ────────────────────────── */

function getDefaultSeparator(variant: BreadcrumbVariant): React.ReactNode {
  switch (variant) {
    case "with-icons":
      return <IconChevronRight className="size-3.5 text-[var(--muted-foreground)] opacity-50" />;
    case "custom-separator":
      return (
        <span className="text-[var(--muted-foreground)] opacity-40 text-xs select-none">
          →
        </span>
      );
    default:
      return <IconSlash className="size-3 text-[var(--muted-foreground)] opacity-40 -rotate-[20deg]" />;
  }
}

/* ─── <Breadcrumb> ──────────────────────────────────────────── */

export const Breadcrumb = React.forwardRef<HTMLElement, BreadcrumbProps>(
  (
    {
      variant = "default",
      separator: customSeparator,
      maxItems = 3,
      className,
      children,
      ...props
    },
    ref,
  ) => {
    const separator = customSeparator ?? getDefaultSeparator(variant);
    const ctx = React.useMemo<BreadcrumbContextValue>(
      () => ({ variant, separator }),
      [variant, separator],
    );

    const items = React.Children.toArray(children);
    const maxVisibleItems = Number.isFinite(maxItems)
      ? Math.max(3, Math.floor(maxItems))
      : 3;

    /* ── Collapsed / Dropdown logic ──────────────────────────── */
    if (
      (variant === "collapsed" || variant === "dropdown") &&
      items.length > maxVisibleItems
    ) {
      const visibleMiddleCount = maxVisibleItems - 3;
      const leadingMiddleCount = Math.floor(visibleMiddleCount / 2);
      const trailingMiddleCount = visibleMiddleCount - leadingMiddleCount;
      const hiddenStartIndex = 1 + leadingMiddleCount;
      const hiddenEndIndex = items.length - 1 - trailingMiddleCount;
      const leadingItems = items.slice(0, hiddenStartIndex);
      const hiddenItems = items.slice(hiddenStartIndex, hiddenEndIndex);
      const trailingItems = items.slice(hiddenEndIndex);

      return (
        <BreadcrumbContext.Provider value={ctx}>
          <nav ref={ref} aria-label="Breadcrumb" className={className} {...props}>
            <ol className="flex items-center gap-1.5">
              {leadingItems.map((child, i) => (
                <React.Fragment key={`leading-${i}`}>
                  {i > 0 && <BreadcrumbSeparatorInternal separator={separator} />}
                  <BreadcrumbItemWrapper>{child}</BreadcrumbItemWrapper>
                </React.Fragment>
              ))}
              <BreadcrumbSeparatorInternal separator={separator} />

              {/* Collapsed middle */}
              <CollapsedMiddle
                variant={variant}
                items={hiddenItems}
                separator={separator}
              />
              <BreadcrumbSeparatorInternal separator={separator} />

              {trailingItems.map((child, i) => (
                <React.Fragment key={`trailing-${i}`}>
                  {i > 0 && <BreadcrumbSeparatorInternal separator={separator} />}
                  <BreadcrumbItemWrapper>{child}</BreadcrumbItemWrapper>
                </React.Fragment>
              ))}
            </ol>
          </nav>
        </BreadcrumbContext.Provider>
      );
    }

    /* ── Standard rendering ──────────────────────────────────── */
    return (
      <BreadcrumbContext.Provider value={ctx}>
        <nav ref={ref} aria-label="Breadcrumb" className={className} {...props}>
          <ol className="flex flex-wrap items-center gap-1.5">
            {items.map((child, i) => (
              <React.Fragment key={i}>
                {i > 0 && <BreadcrumbSeparatorInternal separator={separator} />}
                <BreadcrumbItemWrapper>{child}</BreadcrumbItemWrapper>
              </React.Fragment>
            ))}
          </ol>
        </nav>
      </BreadcrumbContext.Provider>
    );
  },
);
Breadcrumb.displayName = "Breadcrumb";

/* ─── Internal separator ────────────────────────────────────── */

function BreadcrumbSeparatorInternal({
  separator,
}: {
  separator: React.ReactNode;
}) {
  return (
    <li
      role="presentation"
      aria-hidden
      className="flex items-center select-none [&_svg]:size-3"
    >
      {separator}
    </li>
  );
}

/* ─── Item wrapper (thin pass-through for ol semantics) ────── */

function BreadcrumbItemWrapper({ children }: { children: React.ReactNode }) {
  return <>{children}</>;
}

/* ─── <BreadcrumbItem> ──────────────────────────────────────── */

const linkBase = cn(
  "inline-flex items-center gap-1.5 text-sm font-medium leading-none tracking-[-0.01em]",
  "transition-colors duration-[180ms] ease-[cubic-bezier(0.23,1,0.32,1)]",
  "outline-none select-none",
  "focus-visible:ring-2 focus-visible:ring-[color-mix(in_srgb,var(--foreground)_20%,transparent)] focus-visible:rounded-sm focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg]:size-3.5",
);

export const BreadcrumbItem = React.forwardRef<
  HTMLLIElement,
  BreadcrumbItemProps
>(({ href, icon, isCurrentPage, className, children, ...props }, ref) => {
  const { variant } = React.useContext(BreadcrumbContext);
  const content = (
    <BreadcrumbItemContent
      href={href}
      icon={icon}
      isCurrentPage={isCurrentPage}
      className={className}
      variant={variant}
    >
      {children}
    </BreadcrumbItemContent>
  );

  return (
    <li ref={ref} className="flex items-center" {...props}>
      {content}
    </li>
  );
});
BreadcrumbItem.displayName = "BreadcrumbItem";

function BreadcrumbItemContent({
  href,
  icon,
  isCurrentPage,
  className,
  children,
  variant,
}: BreadcrumbItemProps & { variant: BreadcrumbVariant }) {
  const showIcon = variant === "with-icons" && icon;

  if (isCurrentPage || !href) {
    return (
      <span
        aria-current={isCurrentPage ? "page" : undefined}
        className={cn(
          linkBase,
          "text-[var(--foreground)] cursor-default",
          className,
        )}
      >
        {showIcon && icon}
        {children}
      </span>
    );
  }

  return (
    <a
      href={href}
      onClick={(e) => {
        if (href === "#") {
          e.preventDefault();
        }
      }}
      className={cn(
        linkBase,
        "text-[var(--muted-foreground)]",
        "hover:text-[var(--foreground)]",
        "group/crumb relative",
        className,
      )}
    >
      {showIcon && icon}
      <span className="relative">
        {children}
        {/* Underline slide-in from left on hover */}
        <span
          className={cn(
            "absolute -bottom-0.5 left-0 h-px w-full origin-left scale-x-0",
            "bg-[var(--foreground)] opacity-40",
            "transition-transform duration-200 ease-[cubic-bezier(0.23,1,0.32,1)]",
            "group-hover/crumb:scale-x-100",
          )}
        />
      </span>
    </a>
  );
}

/* ─── <BreadcrumbSeparator> (public, for custom-separator) ─── */

export const BreadcrumbSeparator = React.forwardRef<
  HTMLLIElement,
  BreadcrumbSeparatorProps
>(({ className, children, ...props }, ref) => {
  const { separator } = React.useContext(BreadcrumbContext);
  return (
    <li
      ref={ref}
      role="presentation"
      aria-hidden
      className={cn("flex items-center select-none [&_svg]:size-3", className)}
      {...props}
    >
      {children ?? separator}
    </li>
  );
});
BreadcrumbSeparator.displayName = "BreadcrumbSeparator";

/* ─── Collapsed middle items ────────────────────────────────── */

function CollapsedMiddle({
  variant,
  items,
  separator,
}: {
  variant: BreadcrumbVariant;
  items: React.ReactNode[];
  separator: React.ReactNode;
}) {
  const [expanded, setExpanded] = React.useState(false);
  const [dropdownOpen, setDropdownOpen] = React.useState(false);
  const dropdownRef = React.useRef<HTMLLIElement>(null);

  /* Close dropdown on outside click */
  React.useEffect(() => {
    if (!dropdownOpen) return;
    function handleClick(e: MouseEvent) {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(e.target as Node)
      ) {
        setDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, [dropdownOpen]);

  /* ── Collapsed variant: expand inline ───── */
  if (variant === "collapsed") {
    if (expanded) {
      return (
        <>
          {items.map((child, i) => (
            <React.Fragment key={i}>
              <AnimatedBreadcrumbItem child={child} index={i} />
              {i < items.length - 1 && (
                <motion.li
                  role="presentation"
                  aria-hidden
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.15, delay: i * 0.04 + 0.05 }}
                  className="flex items-center select-none [&_svg]:size-3"
                >
                  {separator}
                </motion.li>
              )}
            </React.Fragment>
          ))}
        </>
      );
    }

    return (
      <li className="flex items-center">
        <button
          type="button"
          aria-label={`Show ${items.length} more items`}
          onClick={() => setExpanded(true)}
          className={cn(
            "inline-flex h-6 w-7 items-center justify-center rounded-md",
            "text-[var(--muted-foreground)]",
            "transition-colors duration-[180ms] ease-[cubic-bezier(0.23,1,0.32,1)]",
            "hover:text-[var(--foreground)] hover:bg-[color-mix(in_srgb,var(--foreground)_6%,var(--background))]",
            "focus-visible:ring-2 focus-visible:ring-[color-mix(in_srgb,var(--foreground)_20%,transparent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]",
            "outline-none",
          )}
        >
          <IconDots className="size-3.5" />
        </button>
      </li>
    );
  }

  /* ── Dropdown variant: floating menu ───── */
  return (
    <li className="relative flex items-center" ref={dropdownRef}>
      <button
        type="button"
        aria-label={`Show ${items.length} more items`}
        aria-expanded={dropdownOpen}
        onClick={() => setDropdownOpen((v) => !v)}
        className={cn(
          "inline-flex h-6 w-7 items-center justify-center rounded-md",
          "text-[var(--muted-foreground)]",
          "transition-colors duration-[180ms] ease-[cubic-bezier(0.23,1,0.32,1)]",
          "hover:text-[var(--foreground)] hover:bg-[color-mix(in_srgb,var(--foreground)_6%,var(--background))]",
          "focus-visible:ring-2 focus-visible:ring-[color-mix(in_srgb,var(--foreground)_20%,transparent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]",
          "outline-none",
          dropdownOpen &&
            "text-[var(--foreground)] bg-[color-mix(in_srgb,var(--foreground)_6%,var(--background))]",
        )}
      >
        <IconDots className="size-3.5" />
      </button>

      <AnimatePresence>
        {dropdownOpen && (
          <motion.div
            initial={{ opacity: 0, scale: 0.96, y: 4 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.96, y: 4 }}
            transition={{ duration: 0.18, ease: EASE_OUT }}
            className={cn(
              "absolute bottom-full left-1/2 z-50 mb-2 -translate-x-1/2",
              "min-w-[140px] rounded-xl p-1",
              "border border-[color-mix(in_srgb,var(--foreground)_10%,transparent)]",
              "bg-[var(--background)]",
              "shadow-[0_4px_16px_rgba(0,0,0,0.08),0_1px_4px_rgba(0,0,0,0.04)]",
              "dark:border-white/[0.08]",
              "dark:bg-[color-mix(in_srgb,var(--foreground)_4%,var(--background))]",
              "dark:shadow-[0_4px_16px_rgba(0,0,0,0.40),0_1px_4px_rgba(0,0,0,0.30)]",
            )}
            style={{ transformOrigin: "bottom center" }}
          >
            {items.map((child, i) => {
              /* Extract text/href from BreadcrumbItem children */
              const childEl = child as React.ReactElement<BreadcrumbItemProps>;
              const href = childEl?.props?.href;
              const label = childEl?.props?.children;
              const icon = childEl?.props?.icon;

              return (
                <a
                  key={i}
                  href={href ?? "#"}
                  onClick={(e) => {
                    setDropdownOpen(false);
                    if (!href || href === "#") {
                      e.preventDefault();
                    }
                  }}
                  className={cn(
                    "flex items-center gap-2 rounded-lg px-2.5 py-1.5 text-sm font-medium",
                    "text-[var(--muted-foreground)]",
                    "transition-colors duration-[150ms] ease-[cubic-bezier(0.23,1,0.32,1)]",
                    "hover:text-[var(--foreground)] hover:bg-[color-mix(in_srgb,var(--foreground)_5%,var(--background))]",
                    "outline-none",
                    "[&_svg]:size-3.5 [&_svg]:shrink-0",
                  )}
                >
                  {icon}
                  {label}
                </a>
              );
            })}
          </motion.div>
        )}
      </AnimatePresence>
    </li>
  );
}

function AnimatedBreadcrumbItem({
  child,
  index,
}: {
  child: React.ReactNode;
  index: number;
}) {
  const { variant } = React.useContext(BreadcrumbContext);

  if (!React.isValidElement<BreadcrumbItemProps>(child)) {
    return (
      <li className="flex items-center">
        <motion.div
          initial={{ opacity: 0, y: 4 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{
            duration: 0.2,
            ease: EASE_OUT,
            delay: index * 0.04,
          }}
          className="flex items-center"
        >
          {child}
        </motion.div>
      </li>
    );
  }

  const { href, icon, isCurrentPage, className, children, ...props } =
    child.props;

  return (
    <li {...props} className="flex items-center">
      <motion.div
        initial={{ opacity: 0, y: 4 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{
          duration: 0.2,
          ease: EASE_OUT,
          delay: index * 0.04,
        }}
        className="flex items-center"
      >
        <BreadcrumbItemContent
          href={href}
          icon={icon}
          isCurrentPage={isCurrentPage}
          className={className}
          variant={variant}
        >
          {children}
        </BreadcrumbItemContent>
      </motion.div>
    </li>
  );
}
